/* v19: the Azulejo Playful kit (assets, look tokens for Playful). Owned by the kit step; groups do not edit this file.
   Palette: the panel's own pigments. Cobalt line family #1F3F9A → #0E2466 on warm tin-glaze white #F7F2E7 / paper #FFFDF8;
   antimony yellow #F2C14E is the one warm accent (dark mode's main button); ochre, copper green and manganese are decor fills only.
   Every text pair ≥ 7:1 in both modes (mk_review/v19/kit/src/palette.py). Assets: media/KIDS_*.txt (built by mk_review/v19/kit/src/kitgen.py). */
(() => {
  const P = D.looks && D.looks.playful; if (!P) return;
  Object.assign(P.tokens, { outline_pt: 2, shadow_style: "hard", title_face: "rounded", corner: 24, icon_stroke: 2.25 });
  P.colours = { light: {"glass": {"color": "#FFFDF8", "tint": 0.97, "blur": 0}, "text": {"main": "#0E2466", "soft": "#33447F"}, "border": {"color": "#0E2466", "opacity": 1.0}, "accent": "#1F3F9A", "accent_text": "#FFFFFF", "buttons": {"color": "#FFFDF8", "tint": 1.0, "icon": "#0E2466", "label": "#FFFDF8", "label_text": "#0E2466"}, "tags": {"color": "#FFFDF8", "tint": 1.0}, "sheet": {"color": "#F7F2E7", "tint": 1.0, "text": "#0E2466", "soft": "#33447F"}, "labels": {"color": "#FFFDF8", "tint": 0.96, "text": "#0E2466"}},
    dark: {"glass": {"color": "#1B2456", "tint": 0.98, "blur": 0}, "text": {"main": "#F7F2E7", "soft": "#C9D1F0"}, "border": {"color": "#A9B8F2", "opacity": 1.0}, "accent": "#F2C14E", "accent_text": "#0E2466", "buttons": {"color": "#263070", "tint": 1.0, "icon": "#F7F2E7", "label": "#263070", "label_text": "#F7F2E7"}, "tags": {"color": "#263070", "tint": 1.0}, "sheet": {"color": "#182050", "tint": 1.0, "text": "#F7F2E7", "soft": "#C9D1F0"}, "labels": {"color": "#141B45", "tint": 0.95, "text": "#F7F2E7"}} };
})();
/* the kit, for JS that builds Playful-only DOM (Azu, celebrations, decorations). Over the camera: none of it except Azu in a tip */
const KIDS = {
  decor: { antimony: "#F2C14E", ochre: "#E7AE45", copper: "#8ACBA8", manganese: "#C3B0E3", sky: "#C9D4F0", glyph: "#0E2466" },   // fills only; a glyph on them is cobalt_deep
  azu: { wave: "@@KIDS_AZU_WAVE@@", point: "@@KIDS_AZU_POINT@@", cheer: "@@KIDS_AZU_CHEER@@",   // 200 × 240 (5:6); good from 48 pt tall. PNG 360 × 432 (3x of 120 × 144 pt)
         head: "@@KIDS_AZU_HEAD@@" },   // the head only, 120 × 120 (square): the nav / avatar button (.mazu, kids_30). PNG 216 × 216
  azuD: { wave: "@@KIDS_AZU_WAVE_D@@", point: "@@KIDS_AZU_POINT_D@@", cheer: "@@KIDS_AZU_CHEER_D@@", head: "@@KIDS_AZU_HEAD_D@@" },   // dark: cream glaze #F7F2E7 + lavender cut line (white glared on navy)
  /* the pose for the current mode (Unity: two sprites per pose, swapped by the mode, or one sprite + the cut-line tint) */
  azuSrc: (pose = "wave") => { const A = typeof appearance === "function" && appearance() === "dark" ? KIDS.azuD : KIDS.azu; return A[pose] || A.wave; },
  azuImg: (pose = "wave", cls = "") => h("img", { class: "k-azu " + cls, src: KIDS.azuSrc(pose), alt: "Azu", draggable: "false" }),
  /* the album / sticker art: the tile crop of the panel itself (poiImage), never the modern photo (heroStyle prefers p.media.hero) */
  tileArt: (p, pad = 0.1) => poiImage(p, pad),
  /* a row's own glyph in Playful (Explore, Settings): the experience key → a kit doodle; anything else keeps its icon */
  ROW: { tour_1: "kd_compass", tour_2: "kd_ship", game_1: "kd_puzzle", game_2: "kd_quiz", moment_1: "kd_wave", moment_2: "kd_star" },
  rowIcon: (key, fallback) => (activeLook() === "playful" && KIDS.ROW[key]) || fallback,
  doodle: k => h("span", { class: "k-doodle" }, svg("kd_" + k)),   // sparkle star swirl ship wave rosette compass arrow heart laurel puzzle quiz; colour = currentColor
};
/* doodles as icons (64 grid scaled into the 24 grid; filled with currentColor, no stroke), and Azu as an icon-sized image.
   The SVG markup lives in media/KIDS_ICON_*.txt (inlined by build.py; the same art as KIDS_DOODLE_*, uncoloured). unity: Vector Images, tinted */
Object.assign(ICONS, {
  kd_sparkle: "@@KIDS_ICON_SPARKLE@@",
  kd_star: "@@KIDS_ICON_STAR@@",
  kd_swirl: "@@KIDS_ICON_SWIRL@@",
  kd_ship: "@@KIDS_ICON_SHIP@@",
  kd_wave: "@@KIDS_ICON_WAVE@@",
  kd_rosette: "@@KIDS_ICON_ROSETTE@@",
  kd_compass: "@@KIDS_ICON_COMPASS@@",
  kd_arrow: "@@KIDS_ICON_ARROW@@",
  kd_heart: "@@KIDS_ICON_HEART@@",
  kd_laurel: "@@KIDS_ICON_LAUREL@@",
  kd_puzzle: "@@KIDS_ICON_PUZZLE@@",
  kd_quiz: "@@KIDS_ICON_QUIZ@@",
});
/* Azu as icons: getters, so svg("azu_kids_*") follows the mode at render time */
for (const k of ["wave", "point", "cheer"]) Object.defineProperty(ICONS, "azu_kids_" + k, { enumerable: true, configurable: true, get: () => `<image href="${KIDS.azuSrc(k)}" x="2" y="0" width="20" height="24"/>` });
Object.defineProperty(ICONS, "azu_kids_head", { enumerable: true, configurable: true, get: () => `<image href="${KIDS.azuSrc("head")}" x="0" y="0" width="24" height="24"/>` });
